  {
    SELECT (COUNT(DISTINCT ?asiaCountry) AS ?countAsia) WHERE {
      ?asiaCountry wdt:P31 wd:Q6256 .
      ?asiaCountry wdt:P30 wd:Q48 .
    }
  }
  FILTER (?countEurope > ?countAsia)
}
```

